package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

var reader = bufio.NewReader(os.Stdin)

func readstring() string {
	return readStringFromBuffer(reader)
}

func readint() int32 {
	return readIntFromBuffer(reader)
}

func readStringFromBuffer(r *bufio.Reader) string {
	inputText, err := r.ReadString('\n')
	if err != nil {
		panic("failed to read from stdin")
	}
	return strings.TrimRight(inputText, "\r\n")
}

func readIntFromBuffer(r *bufio.Reader) int32 {
	s := readStringFromBuffer(r)
	val, err := strconv.ParseInt(strings.TrimSpace(s), 10, 32)
	if err != nil {
		panic("couldn't parse data to an integer")
	}
	return int32(val)
}

func read_line_of_integers() []int32 {
	s := readstring()
	parts := strings.Fields(s)
	res := make([]int32, len(parts))
	for i, x := range parts {
		v, err := strconv.ParseInt(x, 10, 32)
		if err != nil {
			panic(err)
		}
		res[i] = int32(v)
	}
	return res
}

func read_line_of_longs() []int64 {
	s := readstring()
	parts := strings.Fields(s)
	res := make([]int64, len(parts))
	for i, x := range parts {
		v, err := strconv.ParseInt(x, 10, 64)
		if err != nil {
			panic(err)
		}
		res[i] = v
	}
	return res
}

func h(par *[]int32, d *[]int32, i int32) int32 {
	if i == 1 {
		return -1
	}
	p := (*par)[i-2]
	if (*d)[i-2] == 0 {
		(*d)[i-2] = h(par, d, p) + 1
	}
	return (*d)[i-2]
}

func main() {
	v := read_line_of_integers()
	a := v[0]
	b := v[1]
	if a > b {
		a, b = b, a
	}
	if int64(a)+int64(v[2]) <= int64(b) {
		fmt.Println(2 * (a + v[2]))
	} else {
		fmt.Println(2*int64(b) + ((int64(v[2])-(int64(b)-int64(a)))/2)*2)
	}
}

